def is_palindrome(s: str) -> bool:
    cleaned = []
    for char in s:
        if char.isalnum():
            cleaned.append(char.lower())
    return cleaned == cleaned[::-1]

def is_palindrome(s):
    cleaned = [char.lower() for char in s if char.isalnum()]
    left, right = 0, len(cleaned) - 1

    while left < right:
        if cleaned[left] != cleaned[right]:
            return False
        left += 1
        right -= 1

    return True

import re

def word_count(text):
    # Find all sequences of letters, digits, or apostrophes
    matches = re.findall(r"[A-Za-z0-9']+", text)
    # Convert to lowercase and count occurrences
    counts = {}
    for word in matches:
        normalized = word.lower()
        counts[normalized] = counts.get(normalized, 0) + 1
    return counts

def flatten(items):
    result = []
    for item in items:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

def flatten(items):
    result = []
    stack = [items]
    while stack:
        current = stack.pop()
        for item in current:
            if isinstance(item, list):
                stack.append(item)
            else:
                result.append(item)
    return result[::-1]  # Reverse to preserve order

def roman_to_int(s):
    roman_map = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }

    total = 0
    n = len(s)

    for i in range(n):
        value = roman_map[s[i]]
        # If the current value is less than the next, it's a subtractive case
        if i + 1 < n and value < roman_map[s[i + 1]]:
            total -= value
        else:
            total += value

    return total

def merge_intervals(intervals):
    if not intervals:
        return []

    # Sort intervals by start time
    intervals.sort(key=lambda x: x[0])

    result = [intervals[0]]

    for i in range(1, len(intervals)):
        current_start, current_end = intervals[i]
        last_start, last_end = result[-1]

        # Merge if current interval overlaps with or touches the last interval
        if current_start <= last_end:
            result[-1] = [last_start, max(last_end, current_end)]
        else:
            result.append([current_start, current_end])

    return result

def two_sum(nums, target):
    """
    Returns a tuple (i, j) with i < j such that nums[i] + nums[j] == target,
    choosing the pair with the smallest j (and then smallest i).
    Returns None if no such pair exists.
    """
    num_to_indices = {}  # value -> list of indices
    for idx, num in enumerate(nums):
        if num not in num_to_indices:
            num_to_indices[num] = []
        num_to_indices[num].append(idx)

    for j in range(len(nums)):
        complement = target - nums[j]
        if complement in num_to_indices:
            for i in num_to_indices[complement]:
                if i < j:
                    return (i, j)

    return None

def two_sum(nums, target):
    """
    Returns a tuple (i, j) with i < j such that nums[i] + nums[j] == target,
    choosing the pair with the smallest j (and then the smallest i).
    Returns None if no such pair exists.
    """
    seen = {}  # value -> list of indices
    for j, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            # seen[complement] is a list of indices i where nums[i] == complement
            for i in seen[complement]:
                if i < j:
                    return (i, j)
        if num not in seen:
            seen[num] = []
        seen[num].append(j)

    return None

def caesar(text: str, shift: int) -> str:
    def shift_char(c: str) -> str:
        if 'a' <= c <= 'z':
            base = ord('a')
            return chr((ord(c) - base + shift) % 26 + base)
        elif 'A' <= c <= 'Z':
            base = ord('A')
            return chr((ord(c) - base + shift) % 26 + base)
        else:
            return c
    return ''.join(shift_char(c) for c in text)

def is_balanced(s: str) -> bool:
    stack = []
    mapping = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in '([{':
            stack.append(char)
        elif char in ')]}':
            if not stack:
                return False
            top = stack.pop()
            if mapping[char] != top:
                return False
        # Ignore other characters

    return len(stack) == 0

def rle_encode(s: str) -> str:
    if not s:
        return ''

    result = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1

    result.append(f"{current_char}{count}")
    return ''.join(result)
